/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.io.IOException;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

import javax.sql.DataSource;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;

import io.quarkus.arc.properties.IfBuildProperty;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.metric.MetricPoint;

/**
 * Store in the database of the application ({@code app.observe.storage=sql}), for volumes where
 * reading whole JSONL days is too slow. Three tables, created at startup if they do not exist
 * ({@code obs_log}, {@code obs_span}, {@code obs_point}): the columns the queries filter by, and
 * the whole event as JSON. Portable JDBC (PostgreSQL, MariaDB / MySQL, H2...): the row limit is
 * {@code setMaxRows}, never a LIMIT clause. The purge deletes by time and by source; the disk limit
 * is the one of the database, not {@code max-disk-mb}.
 */
@ApplicationScoped
@IfBuildProperty(name = "app.observe.storage", stringValue = "sql")
@Slf4j
public class SqlTelemetryStore implements TelemetryStore {

  private static final List<String> LEVELS =
      List.of("TRACE", "DEBUG", "INFO", "WARN", "ERROR", "FATAL");
  private static final int CHUNK = 500;

  private final DataSource dataSource;
  private final ObjectMapper mapper =
      new ObjectMapper().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
  private volatile boolean ready;
  private final TraceLevels levels = new TraceLevels();

  public SqlTelemetryStore(final DataSource dataSource) {
    this.dataSource = dataSource;
  }

  /**
   * Creates the tables and indexes if they do not exist (the index errors of old engines are
   * ignored).
   */
  synchronized void schema() {
    if (ready) {
      return;
    }
    try (Connection connection = dataSource.getConnection();
        Statement statement = connection.createStatement()) {
      String text = textType(connection.getMetaData().getDatabaseProductName());
      statement.execute(
          "CREATE TABLE IF NOT EXISTS obs_log (ts BIGINT NOT NULL, src VARCHAR(200) NOT NULL, "
              + "lvl VARCHAR(10), trace_id VARCHAR(64), fingerprint VARCHAR(64), rel VARCHAR(100), env VARCHAR(50), "
              + "tsev SMALLINT, payload " + text + " NOT NULL)");
      statement.execute(
          "CREATE TABLE IF NOT EXISTS obs_span (ts BIGINT NOT NULL, src VARCHAR(200) NOT NULL, "
              + "trace_id VARCHAR(64), span_id VARCHAR(32), kind VARCHAR(20), status VARCHAR(10), rel VARCHAR(100), "
              + "env VARCHAR(50), tsev SMALLINT, payload " + text + " NOT NULL)");
      statement.execute(
          "CREATE TABLE IF NOT EXISTS obs_point (ts BIGINT NOT NULL, step BIGINT NOT NULL, "
              + "src VARCHAR(200) NOT NULL, method VARCHAR(20), route VARCHAR(400), payload " + text
              + " NOT NULL)");
      for (String column : new String[] {"ALTER TABLE obs_log ADD tsev SMALLINT",
          "ALTER TABLE obs_span ADD tsev SMALLINT"}) {
        try (Statement alter = connection.createStatement()) {
          alter.execute(column);
        } catch (SQLException ex) {
          // Tables created with the column
        }
      }
      for (String index : new String[] {"CREATE INDEX obs_log_ts ON obs_log (ts)",
          "CREATE INDEX obs_log_src_ts ON obs_log (src, ts)",
          "CREATE INDEX obs_log_trace ON obs_log (trace_id)",
          "CREATE INDEX obs_log_fp ON obs_log (fingerprint)",
          "CREATE INDEX obs_span_ts ON obs_span (ts)",
          "CREATE INDEX obs_span_src_ts ON obs_span (src, ts)",
          "CREATE INDEX obs_span_trace ON obs_span (trace_id)",
          "CREATE INDEX obs_point_ts ON obs_point (step, ts)"}) {
        try (Statement create = connection.createStatement()) {
          create.execute(index);
        } catch (SQLException ex) {
          // It already exists
        }
      }
      ready = true;
    } catch (SQLException ex) {
      throw new IllegalStateException(
          "Unable to create the observability tables: " + ex.getMessage(), ex);
    }
  }

  /** Type of the payload column for an engine. */
  static String textType(final String product) {
    String name = null == product ? "" : product.toLowerCase(Locale.ROOT);
    if (name.contains("postgres")) {
      return "TEXT";
    }
    if (name.contains("mysql") || name.contains("mariadb")) {
      return "MEDIUMTEXT";
    }
    return "CLOB";
  }

  /**
   * Each row keeps the level of its trace in {@code tsev} ({@link TraceLevels}); when a batch
   * raises the level of a trace, the rows it already has are marked with the new one.
   */
  @Override
  public void appendLogs(final List<ObsLog> logs) {
    Map<String, Integer> raised = levels.raise(logs, List.of());
    insert(
        "INSERT INTO obs_log (ts, src, lvl, trace_id, fingerprint, rel, env, payload, tsev) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        logs, (statement, log) -> {
          statement.setLong(1, log.ts());
          statement.setString(2, log.src());
          statement.setString(3, log.level());
          statement.setString(4, log.traceId());
          Object fingerprint = null == log.attrs() ? null : log.attrs().get("issue.fingerprint");
          statement.setString(5, null == fingerprint ? null : String.valueOf(fingerprint));
          statement.setString(6, cut(log.release(), 100));
          statement.setString(7, cut(log.env(), 50));
          statement.setString(8, json(log));
          statement.setInt(9,
              TraceLevels.effective(TraceLevels.of(log), levels.level(log.traceId())));
        });
    mark(raised);
  }

  @Override
  public void appendSpans(final List<ObsSpan> spans) {
    Map<String, Integer> raised = levels.raise(List.of(), spans);
    insert(
        "INSERT INTO obs_span (ts, src, trace_id, span_id, kind, status, rel, env, payload, tsev) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        spans, (statement, span) -> {
          statement.setLong(1, span.ts());
          statement.setString(2, span.src());
          statement.setString(3, span.traceId());
          statement.setString(4, span.spanId());
          statement.setString(5, span.kind());
          statement.setString(6, span.status());
          statement.setString(7, cut(span.release(), 100));
          statement.setString(8, cut(span.env(), 50));
          statement.setString(9, json(span));
          statement.setInt(10,
              TraceLevels.effective(TraceLevels.of(span), levels.level(span.traceId())));
        });
    mark(raised);
  }

  /** The rows already stored of the traces whose level rose take the new one. */
  private void mark(final Map<String, Integer> raised) {
    if (raised.isEmpty()) {
      return;
    }
    schema();
    try (Connection connection = dataSource.getConnection()) {
      for (String table : new String[] {"obs_log", "obs_span"}) {
        try (PreparedStatement statement = connection.prepareStatement("UPDATE " + table
            + " SET tsev = ? WHERE trace_id = ? AND (tsev IS NULL OR tsev < ?)")) {
          for (Map.Entry<String, Integer> trace : raised.entrySet()) {
            statement.setInt(1, trace.getValue());
            statement.setString(2, trace.getKey());
            statement.setInt(3, trace.getValue());
            statement.addBatch();
          }
          statement.executeBatch();
        }
      }
    } catch (SQLException ex) {
      log.warn("Unable to mark the level of {} traces: {}", raised.size(), ex.getMessage());
    }
  }

  @Override
  public void appendPoints(final List<MetricPoint> points) {
    insert(
        "INSERT INTO obs_point (ts, step, src, method, route, payload) VALUES (?, ?, ?, ?, ?, ?)",
        points, (statement, point) -> {
          statement.setLong(1, point.ts());
          statement.setLong(2, point.step());
          statement.setString(3, point.src());
          statement.setString(4, point.method());
          statement.setString(5, cut(point.route(), 400));
          statement.setString(6, json(point));
        });
  }

  @Override
  public List<ObsLog> logs(final TelemetryQuery query) {
    Where where = new Where().range(query).sources(query.getSources());
    query.getMinLevel().ifPresent(min -> where.in("lvl", levelsFrom(min)));
    if (query.isErrors()) {
      where.in("lvl", List.of("ERROR", "FATAL"));
    }
    query.getTraceId().ifPresent(id -> where.eq("trace_id", id));
    query.getFingerprint().ifPresent(fp -> where.eq("fingerprint", fp));
    query.getRelease().ifPresent(release -> where.eq("rel", release));
    query.getEnv().ifPresent(env -> where.eq("env", env));
    query.getText().ifPresent(where::like);
    return select("SELECT payload FROM obs_log" + where.sql() + " ORDER BY ts DESC", where.args(),
        query.getLimit(), ObsLog.class);
  }

  @Override
  public List<ObsSpan> spans(final TelemetryQuery query) {
    Where where = new Where().range(query).sources(query.getSources());
    if (query.isErrors()) {
      where.eq("status", "ERROR");
    }
    query.getTraceId().ifPresent(id -> where.eq("trace_id", id));
    query.getRelease().ifPresent(release -> where.eq("rel", release));
    query.getEnv().ifPresent(env -> where.eq("env", env));
    query.getText().ifPresent(where::like);
    return select("SELECT payload FROM obs_span" + where.sql() + " ORDER BY ts DESC", where.args(),
        query.getLimit(), ObsSpan.class);
  }

  @Override
  public List<ObsSpan> trace(final String traceId, final long from, final long to) {
    return traces(Set.of(traceId), from, to);
  }

  @Override
  public List<ObsSpan> traces(final Set<String> traceIds, final long from, final long to) {
    List<ObsSpan> result = new ArrayList<>();
    List<String> ids = new ArrayList<>(traceIds);
    for (int i = 0; i < ids.size(); i += CHUNK) {
      Where where = new Where().between(from, to).in("trace_id",
          ids.subList(i, Math.min(ids.size(), i + CHUNK)));
      result.addAll(select("SELECT payload FROM obs_span" + where.sql(), where.args(), 50_000,
          ObsSpan.class));
    }
    result.sort(Comparator.comparingLong(ObsSpan::ts));
    return result;
  }

  @Override
  public List<MetricPoint> points(final long from, final long to, final long step,
      final Set<String> sources) {
    Where where = new Where().between(from, to).eq("step", step).sources(sources);
    return select("SELECT payload FROM obs_point" + where.sql() + " ORDER BY ts", where.args(),
        500_000, MetricPoint.class);
  }

  /** The size is the one of the database: it is not measured here. */
  @Override
  public long sizeBytes() {
    return 0;
  }

  @Override
  public void purge(final RetentionPolicy policy) {
    long now = System.currentTimeMillis();
    long day = 86_400_000L;
    delete("DELETE FROM obs_log WHERE ts < ?", now - policy.logsDays() * day);
    delete("DELETE FROM obs_span WHERE ts < ?", now - policy.tracesDays() * day);
    delete("DELETE FROM obs_point WHERE step < 3600000 AND ts < ?",
        now - Math.max(1, policy.metricsDays()) * day);
    delete("DELETE FROM obs_point WHERE step >= 3600000 AND ts < ?",
        now - Math.max(1, policy.rollupDays()) * day);
    if (null != policy.sourceDays()) {
      for (Map.Entry<String, Integer> source : policy.sourceDays().entrySet()) {
        long limit = now - source.getValue() * day;
        delete("DELETE FROM obs_log WHERE src = ? AND ts < ?", source.getKey(), limit);
        delete("DELETE FROM obs_span WHERE src = ? AND ts < ?", source.getKey(), limit);
      }
    }
  }

  /**
   * Rows of each level of trace older than its hours; the rows stored before the column count as
   * INFO.
   */
  @Override
  public void purgeLevels(final RetentionPolicy policy) {
    RetentionPolicy.LevelRetention retention = policy.levels();
    if (null == retention || !retention.enabled()) {
      return;
    }
    long now = System.currentTimeMillis();
    for (int level = TraceLevels.DEBUG; level <= TraceLevels.ERROR; level++) {
      int hours = retention.hours(level);
      if (hours <= 0) {
        continue;
      }
      String which = TraceLevels.INFO == level ? "(tsev = ? OR tsev IS NULL)" : "tsev = ?";
      for (String table : new String[] {"obs_log", "obs_span"}) {
        delete("DELETE FROM " + table + " WHERE ts < ? AND " + which, now - hours * 3_600_000L,
            level);
      }
    }
  }

  /** The levels at least as severe as {@code min}. */
  static List<String> levelsFrom(final String min) {
    int index = LEVELS.indexOf(Levels.normalize(min));
    return index < 0 ? LEVELS : LEVELS.subList(index, LEVELS.size());
  }

  /** Builder of a WHERE clause with its arguments. */
  static final class Where {
    private final StringBuilder sql = new StringBuilder();
    private final List<Object> args = new ArrayList<>();

    Where range(final TelemetryQuery query) {
      return between(query.getFrom(), query.getTo());
    }

    Where between(final long from, final long to) {
      and("ts >= ? AND ts < ?");
      args.add(from);
      args.add(to);
      return this;
    }

    Where eq(final String column, final Object value) {
      and(column + " = ?");
      args.add(value);
      return this;
    }

    Where in(final String column, final List<String> values) {
      if (values.isEmpty()) {
        and("1 = 0");
        return this;
      }
      and(column + " IN (" + String.join(", ", java.util.Collections.nCopies(values.size(), "?"))
          + ")");
      args.addAll(values);
      return this;
    }

    Where sources(final Set<String> sources) {
      return null == sources || sources.isEmpty() ? this : in("src", new ArrayList<>(sources));
    }

    /** Case insensitive text in the event (the JSON with the message and the attributes). */
    Where like(final String text) {
      and("LOWER(payload) LIKE ? ESCAPE '!'");
      args.add("%"
          + text.toLowerCase(Locale.ROOT).replace("!", "!!").replace("%", "!%").replace("_", "!_")
          + "%");
      return this;
    }

    private void and(final String condition) {
      sql.append(sql.length() == 0 ? " WHERE " : " AND ").append(condition);
    }

    String sql() {
      return sql.toString();
    }

    List<Object> args() {
      return args;
    }
  }

  @FunctionalInterface
  private interface Binder<T> {
    void bind(PreparedStatement statement, T item) throws SQLException;
  }

  private <T> void insert(final String sql, final List<T> items, final Binder<T> binder) {
    if (items.isEmpty()) {
      return;
    }
    schema();
    try (Connection connection = dataSource.getConnection();
        PreparedStatement statement = connection.prepareStatement(sql)) {
      for (T item : items) {
        binder.bind(statement, item);
        statement.addBatch();
      }
      statement.executeBatch();
    } catch (SQLException ex) {
      throw new IllegalStateException(
          "Unable to store " + items.size() + " events: " + ex.getMessage(), ex);
    }
  }

  private <T> List<T> select(final String sql, final List<Object> args, final int limit,
      final Class<T> type) {
    schema();
    List<T> result = new ArrayList<>();
    try (Connection connection = dataSource.getConnection();
        PreparedStatement statement = connection.prepareStatement(sql)) {
      statement.setMaxRows(Math.max(1, limit));
      for (int i = 0; i < args.size(); i++) {
        statement.setObject(i + 1, args.get(i));
      }
      try (ResultSet rows = statement.executeQuery()) {
        while (rows.next()) {
          try {
            result.add(mapper.readValue(rows.getString(1), type));
          } catch (IOException ex) {
            // A row that is not readable is skipped
          }
        }
      }
    } catch (SQLException ex) {
      log.warn("Unable to query the observability store: {}", ex.getMessage());
    }
    return result;
  }

  private void delete(final String sql, final Object... args) {
    schema();
    try (Connection connection = dataSource.getConnection();
        PreparedStatement statement = connection.prepareStatement(sql)) {
      for (int i = 0; i < args.length; i++) {
        statement.setObject(i + 1, args[i]);
      }
      statement.executeUpdate();
    } catch (SQLException ex) {
      log.warn("Unable to purge the observability store: {}", ex.getMessage());
    }
  }

  private String json(final Object value) throws SQLException {
    try {
      return mapper.writeValueAsString(value);
    } catch (IOException ex) {
      throw new SQLException("Unable to serialize the event", ex);
    }
  }

  private static String cut(final String value, final int max) {
    return null == value || value.length() <= max ? value : value.substring(0, max);
  }
}
